using EventLensAI.Domain.Entities;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace EventLensAI.Infrastructure.Persistence.Configurations;
internal sealed class ProfessionalCameraConfiguration:IEntityTypeConfiguration<ProfessionalCamera>{public void Configure(EntityTypeBuilder<ProfessionalCamera>b){b.ToTable("professional_cameras");b.ConfigureBase();b.Property(x=>x.ProviderType).HasConversion<string>().HasMaxLength(30);b.Property(x=>x.Status).HasConversion<string>().HasMaxLength(30);b.Property(x=>x.Name).HasMaxLength(100);b.Property(x=>x.Model).HasMaxLength(100);b.Property(x=>x.SerialNumber).HasMaxLength(200);b.Property(x=>x.ConnectionType).HasMaxLength(30);b.Property(x=>x.FirmwareVersion).HasMaxLength(100);b.Property(x=>x.LastErrorCode).HasMaxLength(100);b.HasIndex(x=>x.OrganizationId);b.HasIndex(x=>x.ProviderType);b.HasIndex(x=>x.Status);b.HasIndex(x=>x.LastConnectedAt);b.HasOne<Organization>().WithMany().HasForeignKey(x=>x.OrganizationId).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class CameraAdapterConfiguration:IEntityTypeConfiguration<CameraAdapter>{public void Configure(EntityTypeBuilder<CameraAdapter>b){b.ToTable("camera_adapters");b.ConfigureBase();b.Property(x=>x.ProviderType).HasConversion<string>().HasMaxLength(30);b.Property(x=>x.AdapterKey).HasMaxLength(100);b.Property(x=>x.Version).HasMaxLength(30);b.HasIndex(x=>new{x.OrganizationId,x.ProfessionalCameraId}).IsUnique().HasFilter("[IsDeleted] = 0");b.HasOne<Organization>().WithMany().HasForeignKey(x=>x.OrganizationId).OnDelete(DeleteBehavior.Restrict);b.HasOne<ProfessionalCamera>().WithMany().HasForeignKey(x=>x.ProfessionalCameraId).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class CameraConnectionLogConfiguration:IEntityTypeConfiguration<CameraConnectionLog>{public void Configure(EntityTypeBuilder<CameraConnectionLog>b){b.ToTable("camera_connection_logs");b.ConfigureBase();b.Property(x=>x.Action).HasMaxLength(40);b.Property(x=>x.Status).HasMaxLength(30);b.Property(x=>x.ErrorCode).HasMaxLength(100);b.HasIndex(x=>x.OrganizationId);b.HasIndex(x=>x.ProfessionalCameraId);b.HasIndex(x=>x.OccurredAt);b.HasOne<Organization>().WithMany().HasForeignKey(x=>x.OrganizationId).OnDelete(DeleteBehavior.Restrict);b.HasOne<ProfessionalCamera>().WithMany().HasForeignKey(x=>x.ProfessionalCameraId).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class CameraCapabilityProfileConfiguration:IEntityTypeConfiguration<CameraCapabilityProfile>{public void Configure(EntityTypeBuilder<CameraCapabilityProfile>b){b.ToTable("camera_capability_profiles");b.ConfigureBase();b.Property(x=>x.Resolution).HasMaxLength(100);b.Property(x=>x.SupportedModes).HasMaxLength(500);b.Property(x=>x.ShutterSpeed).HasMaxLength(500);b.Property(x=>x.Aperture).HasMaxLength(500);b.Property(x=>x.FocusModes).HasMaxLength(500);b.HasIndex(x=>new{x.OrganizationId,x.ProfessionalCameraId}).IsUnique().HasFilter("[IsDeleted] = 0");b.HasOne<Organization>().WithMany().HasForeignKey(x=>x.OrganizationId).OnDelete(DeleteBehavior.Restrict);b.HasOne<ProfessionalCamera>().WithMany().HasForeignKey(x=>x.ProfessionalCameraId).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class ProfessionalCameraEventConfiguration:IEntityTypeConfiguration<ProfessionalCameraEvent>{public void Configure(EntityTypeBuilder<ProfessionalCameraEvent>b){b.ToTable("camera_events");b.ConfigureBase();b.Property(x=>x.EventType).HasConversion<string>().HasMaxLength(40);b.Property(x=>x.Metadata).HasColumnType("nvarchar(max)");b.HasIndex(x=>x.OrganizationId);b.HasIndex(x=>x.ProfessionalCameraId);b.HasIndex(x=>x.OccurredAt);b.HasOne<Organization>().WithMany().HasForeignKey(x=>x.OrganizationId).OnDelete(DeleteBehavior.Restrict);b.HasOne<ProfessionalCamera>().WithMany().HasForeignKey(x=>x.ProfessionalCameraId).OnDelete(DeleteBehavior.Restrict);b.HasOne<BoothSession>().WithMany().HasForeignKey(x=>x.BoothSessionId).OnDelete(DeleteBehavior.Restrict);}}
